('SUB-wPTu3V', 'TCR-ar45dgU', '[{"id":"EX-GEO1","questions":"Lapisan atmosfer yang berperan penting dalam memantulkan gelombang radio adalah?","answerPg":{"answer_a":"Troposfer","answer_b":"Stratosfer","answer_c":"Mesosfer","answer_d":"Termosfer (ionosfer)","answer_e":"Eksosfer"},"correctAnswer":"Termosfer (ionosfer)"},{"id":"EX-GEO2","questions":"Gunung berapi yang terbentuk dari letusan magma yang bersifat cair dan membentuk lereng landai disebut?","answerPg":{"answer_a":"Stratovolcano","answer_b":"Perisai (shield volcano)","answer_c":"Maar","answer_d":"Kaldera","answer_e":"Dome"},"correctAnswer":"Perisai (shield volcano)"},{"id":"EX-GEO3","questions":"Iklim menurut klasifikasi Koppen yang bercirikan curah hujan tinggi sepanjang tahun adalah?","answerPg":{"answer_a":"Af (hutan hujan tropis)","answer_b":"Aw (sabana tropis)","answer_c":"Bs (stepa)","answer_d":"Bw (gurun)","answer_e":"Cf (iklim sedang basah)"},"correctAnswer":"Af (hutan hujan tropis)"},{"id":"EX-GEO4","questions":"Proses pelapukan batuan akibat perubahan suhu harian tanpa melibatkan makhluk hidup disebut?","answerPg":{"answer_a":"Pelapukan mekanis","answer_b":"Pelapukan kimiawi","answer_c":"Pelapukan biologis","answer_d":"Erosi","answer_e":"Sedimentasi"},"correctAnswer":"Pelapukan mekanis"},{"id":"EX-GEO5","questions":"Benua yang paling sedikit jumlah negara anggotanya adalah?","answerPg":{"answer_a":"Asia","answer_b":"Eropa","answer_c":"Oseania","answer_d":"Antartika","answer_e":"Afrika"},"correctAnswer":"Antartika"},{"id":"EX-GEO6","questions":"Fenomena El Nino di Indonesia biasanya menyebabkan?","answerPg":{"answer_a":"Musim hujan lebih panjang","answer_b":"Musim kemarau lebih panjang","answer_c":"Suhu udara lebih dingin","answer_d":"Peningkatan curah hujan","answer_e":"Angin barat bertiup lebih kuat"},"correctAnswer":"Musim kemarau lebih panjang"},{"id":"EX-GEO7","questions":"Garis khayal yang membagi bumi menjadi dua belahan, utara dan selatan disebut?","answerPg":{"answer_a":"Garis Bujur","answer_b":"Garis Tanggal Internasional","answer_c":"Garis Khatulistiwa","answer_d":"Garis Wallace","answer_e":"Tropis Capricornus"},"correctAnswer":"Garis Khatulistiwa"},{"id":"EX-GEO8","questions":"Jenis batuan yang terbentuk akibat pendinginan magma disebut?","answerPg":{"answer_a":"Batuan beku","answer_b":"Batuan sedimen","answer_c":"Batuan metamorf","answer_d":"Batuan organik","answer_e":"Batuan kimia"},"correctAnswer":"Batuan beku"},{"id":"EX-GEO9","questions":"Delta sungai terbentuk di?","answerPg":{"answer_a":"Hulu sungai","answer_b":"Lereng gunung","answer_c":"Muara sungai","answer_d":"Dasar laut dalam","answer_e":"Danau"},"correctAnswer":"Muara sungai"},{"id":"EX-GEO10","questions":"Negara kepulauan terbesar di dunia berdasarkan jumlah pulau adalah?","answerPg":{"answer_a":"Filipina","answer_b":"Indonesia","answer_c":"Jepang","answer_d":"Maladewa","answer_e":"Fiji"},"correctAnswer":"Indonesia"},{"id":"EX-GEO11","questions":"Fenomena pergerakan lempeng tektonik yang saling bertumbukan dapat menyebabkan?","answerPg":{"answer_a":"Gempa bumi dan tsunami","answer_b":"Hujan deras","answer_c":"Angin muson","answer_d":"Ozon menipis","answer_e":"Iklim tropis"},"correctAnswer":"Gempa bumi dan tsunami"},{"id":"EX-GEO12","questions":"Negara yang berbatasan langsung dengan Indonesia di daratan adalah?","answerPg":{"answer_a":"Singapura","answer_b":"Timor Leste","answer_c":"Filipina","answer_d":"Malaysia","answer_e":"Papua Nugini"},"correctAnswer":"Timor Leste"},{"id":"EX-GEO13","questions":"Jenis angin yang bertiup secara periodik setiap 6 bulan sekali di Asia Tenggara disebut?","answerPg":{"answer_a":"Angin darat","answer_b":"Angin laut","answer_c":"Angin muson","answer_d":"Angin fohn","answer_e":"Angin passat"},"correctAnswer":"Angin muson"},{"id":"EX-GEO14","questions":"Hutan hujan tropis banyak dijumpai di wilayah?","answerPg":{"answer_a":"Kutub utara","answer_b":"Gurun Sahara","answer_c":"Amazon, Kongo, dan Indonesia","answer_d":"Eropa Barat","answer_e":"Australia Tengah"},"correctAnswer":"Amazon, Kongo, dan Indonesia"},{"id":"EX-GEO15","questions":"Pulau Jawa termasuk ke dalam jalur pegunungan muda dunia yang disebut?","answerPg":{"answer_a":"Sirkum Pasifik","answer_b":"Sirkum Mediterania","answer_c":"Pegunungan Himalaya","answer_d":"Alpina","answer_e":"Rocky Mountains"},"correctAnswer":"Sirkum Pasifik"},{"id":"EX-GEO16","questions":"Sumber energi yang berasal dari panas bumi disebut?","answerPg":{"answer_a":"Energi surya","answer_b":"Energi fosil","answer_c":"Energi geotermal","answer_d":"Energi biomassa","answer_e":"Energi pasang surut"},"correctAnswer":"Energi geotermal"},{"id":"EX-GEO17","questions":"Negara dengan luas wilayah terbesar di dunia adalah?","answerPg":{"answer_a":"Cina","answer_b":"Kanada","answer_c":"Amerika Serikat","answer_d":"Rusia","answer_e":"Brazil"},"correctAnswer":"Rusia"}]', 'Ujian Mata Pelajaran Geografi', 'PG')

